package org.apache.commons.math.distribution;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math.exception.NotStrictlyPositiveException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.special.Erf;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math3.exception.MathException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NormalDistributionImpl#cumulativeProbability
 */
public class NormalDistributionImpl_cumulativeProbability_TriageGen0Test {

    private static final double DELTA = 1e-9;

    @Test
    public void testCumulativeProbability_FarLeftTail() throws MathException {
        double mean = 10.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // dev = -50 - 10 = -60. 
        // abs(-60) > 40 * 1 is true. dev < 0 is true. Return 0.0
        double result = dist.cumulativeProbability(-50.0);
        Assert.assertEquals(0.0, result, DELTA);
    }

    @Test
    public void testCumulativeProbability_FarRightTail() throws MathException {
        double mean = 10.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // dev = 50 - 10 = 40. 
        // abs(40) > 40 * 1 is false (it's equal). 
        // Let's push it further to ensure the branch is hit.
        double result = dist.cumulativeProbability(60.0);
        Assert.assertEquals(1.0, result, DELTA);
    }

    @Test
    public void testCumulativeProbability_AtMean() throws MathException {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // dev = 0 - 0 = 0.
        // abs(0) > 40 is false.
        // erf(0) = 0. Result = 0.5 * (1 + 0) = 0.5
        double result = dist.cumulativeProbability(0.0);
        Assert.assertEquals(0.5, result, DELTA);
    }

    @Test
    public void testCumulativeProbability_StandardNormalOneSigma() throws MathException {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // x = 1.0. dev = 1.0.
        // erf(1.0 / sqrt(2)) is approx 0.682689...
        // result = 0.5 * (1 + 0.682689...) approx 0.8413447
        double result = dist.cumulativeProbability(1.0);
        Assert.assertEquals(0.8413447460685429, result, 1e-7);
    }

    @Test
    public void testCumulativeProbability_BoundaryConditionForBranch() throws MathException {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // Testing the exact boundary of the if condition: abs(dev) == 40 * sd
        // dev = 40. abs(40) > 40 is false.
        // This tests the transition from the 'if' block to the 'return' calculation.
        double result = dist.cumulativeProbability(40.0);
        // Since 40 is very far in the tail, the erf value will be very close to 1.0
        Assert.assertTrue(result > 0.999999);
        Assert.assertTrue(result <= 1.0);
    }

    @Test
    public void testCumulativeProbability_NegativeDevBoundary() throws MathException {
        double mean = 0.0;
        double sd = 1.0;
        NormalDistributionImpl dist = new NormalDistributionImpl(mean, sd);

        // dev = -41. abs(-41) > 40 is true. dev < 0 is true. Return 0.0
        double result = dist.cumulativeProbability(-41.0);
        Assert.assertEquals(0.0, result, DELTA);
    }
}
